After these steps, I still got an email warning because of the `NotificationService` app extension added by customer.io which uses `NSPrivacyAccessedAPICategoryUserDefaults` privacy accessed API.
To resolve this we need to add target membership of `NotificationService` to the `PrivacyInfo.xcprivacy` file. Since the expo `privacyManifests` feature only adds the main application as target for this file, I have to write a plugin to add a target for this:
```javascript
const { withXcodeProject } = require('@expo/config-plugins');
const {
  findNativeTargetByName,
} = require('@expo/config-plugins/build/ios/Target');

const withNotificationServicePrivacyInfo = (config) => {
  return withXcodeProject(config, (projectConfig) => {
    const project = projectConfig.modResults;

    const [targetUuid, target] = findNativeTargetByName(
      project,
      'NotificationService',
    );

    const resourcesBuildPhaseUuid = target.buildPhases.find(
      (phase) => phase.comment === 'Resources',
    ).value;

    if (
      project.hash.project.objects['PBXResourcesBuildPhase'][
        resourcesBuildPhaseUuid
      ].files.length > 0
    ) {
      console.warn(
        'Privacy manifest is already in NotificationService target resources',
      );
      return projectConfig;
    }

    const [_, privacyManifestFile] = Object.entries(
      project.pbxBuildFileSection(),
    ).find(
      ([_, value]) =>
        typeof value === 'object' &&
        value.fileRef_comment === 'PrivacyInfo.xcprivacy',
    );

    const file = {
      basename: 'PrivacyInfo.xcprivacy',
      uuid: project.generateUuid(),
      target: targetUuid,
      fileRef: privacyManifestFile.fileRef,
      group: 'Resources',
    };
    project.addToPbxBuildFileSection(file);
    project.addToPbxResourcesBuildPhase(file);

    return projectConfig;
  });
};

module.exports = withNotificationServicePrivacyInfo;
```
Then the email warning seems to be gone.

